406: /** Run `fn` over `items` with at most `width` in flight. */
407: async function pool(items, width, fn) {
408:   const queue = [...items];
409:   const worker = async () => { while (queue.length) await fn(queue.shift()); };
410:   await Promise.all(Array.from({ length: Math.max(1, Math.min(width, queue.length)) }, worker));
411: }

