121: /**
122:  * The effort for a depth on a model's OWN documented ladder, proportionally: depth index d of 0..4 maps to
123:  * rung round(d * (n - 1) / 4) of the model's n documented values. No documented ladder, or a transport that
124:  * does not carry effort, gives none -- and says which.
125:  */
126: export function effortForDepth(depth, { vendor, model }) {
127:   const d = DIMENSIONS.depth.indexOf(depth);
128:   if (d === -1) throw new Error(`unknown depth "${depth}"`);
129:   if (!carriesEffort({ vendor, model })) return { value: null, depth, ladder: [], mapped: `none: effort is not carried by the agy transport for ${model}` };
130:   const ladder = documentedEfforts(model);
131:   if (!ladder.length) return { value: null, depth, ladder: [], mapped: `none: ${model} has no documented effort ladder (capability-facts.json)` };
132:   const i = Math.round(d * (ladder.length - 1) / (DIMENSIONS.depth.length - 1));
133:   return { value: ladder[i], depth, ladder: [...ladder], index: i,
134:     mapped: `depth ${depth} (${d}/${DIMENSIONS.depth.length - 1}) -> rung ${i}/${ladder.length - 1} "${ladder[i]}" of ${model}'s documented ladder [${ladder}]` };
135: }

