512:  * Remove the worktrees a dead run left under `root` (registered or not): `git worktree prune`, then every worktree of
513:  * `repo` whose path is inside `root` is removed (force), and whatever is left in `root` is deleted. Returns the paths
514:  * removed. The caller holds the run directory (liveOwner): nothing a live run uses is under `root`.
515:  */
516: export async function recoverOrphanWorktrees({ repo, root, lock = fn => fn() }) {
517:   if (!existsSync(root)) return [];
518:   const roots = [resolve(root)];
519:   try { roots.push(realpathSync(root)); } catch { /* gone */ }
520:   const under = p => roots.some(r => p === r || p.startsWith(r + sep));
521:   return lock(async () => {
522:     await git(repo, ["worktree", "prune"], { allowFail: true });
523:     const listed = await git(repo, ["worktree", "list", "--porcelain"], { allowFail: true });
524:     const removed = [];
525:     for (const line of String(listed.stdout ?? "").split("\n")) {
526:       if (!line.startsWith("worktree ")) continue;
527:       const p = line.slice("worktree ".length).trim();
528:       if (!under(p)) continue;
529:       const r = await git(repo, ["worktree", "remove", "--force", p], { allowFail: true });
530:       if (r.code !== 0) await rm(p, { recursive: true, force: true });
531:       removed.push(p);
532:     }
533:     for (const name of readdirSync(root)) { const p = join(root, name); if (!removed.includes(p)) removed.push(p); await rm(p, { recursive: true, force: true }); }
534:     await git(repo, ["worktree", "prune"], { allowFail: true });
535:     return removed;
536:   });
