22:   const [{ default: OpenAI }, { GoogleGenAI }, { default: Anthropic }, { makeClient, sendTurn }] = await Promise.all([
23:     import("openai"), import("@google/genai"), import("@anthropic-ai/sdk"), import("./adapter.mjs")]);
24:   const clients = new Map();
25:   // `extra` carries per-seat request options (e.g. reasoning.context for an OpenAI reviewer); only OpenAI receives it.
26:   // `signal` aborts the in-flight request (a stage stopped at its elapsed budget does not wait for it).
27:   const api = async ({ vendor, model, prompt, extra = null, signal = undefined }) => {
28:     if (!clients.has(vendor)) clients.set(vendor, makeClient(vendor, { OpenAI, GoogleGenAI, Anthropic }));
29:     signal?.throwIfAborted();
30:     const r = await sendTurn({ client: clients.get(vendor), vendor, model, prompt, label: `${vendor}-${label}`,
31:       ...(vendor === "openai" && extra && Object.keys(extra).length ? { extra } : {}), ...(signal ? { signal } : {}) });
32:     if (r.complete === false) throw new Error(`${vendor}/${model}: the reply did not complete (${r.terminal_state ?? "unknown"})`);
33:     return { text: r.text ?? "", response_id: r.response_id ?? null, served_model: r.served_model ?? null };
