10: /**
11:  * The read-only binds a tool under the bound /usr needs beyond /usr itself. On Debian-family hosts
12:  * /usr/bin/python3 (and many more) is a symlink into /etc/alternatives, which points back into /usr;
13:  * binding /usr alone leaves that link dangling inside the sandbox (independent review 2026-11-16,
14:  * WF3). Each symlink in `binDirs` is followed link by link, and every directory in `bindable` the
15:  * chain passes through is bound read-only at the same path. Nothing else is exposed: a link that
16:  * leaves /usr for anywhere but a `bindable` directory stays dangling, as before.
17:  */
18: export function toolLinkBinds({ binDirs = ["/usr/bin", "/usr/sbin"], bindable = ["/etc/alternatives"] } = {}) {
19:   const needed = new Set();
20:   for (const dir of binDirs) {
21:     let names; try { names = readdirSync(dir); } catch { continue; }
22:     for (const name of names) {
23:       let p = resolve(dir, name);
24:       for (let hop = 0; hop < 16; hop++) {
25:         let st; try { st = lstatSync(p); } catch { break; }
26:         if (!st.isSymbolicLink()) break;
27:         p = resolve(dirname(p), readlinkSync(p));
28:         const b = bindable.find(d => under(d, p));
29:         if (b) needed.add(b);
30:       }
31:     }
32:   }
33:   return [...needed].sort().flatMap(d => ["--ro-bind", d, d]);
