42:     "--ro-bind", "/usr", "/usr", ...toolLinkBinds(),
43:     "--dir", "/tools", "--ro-bind", realpathSync(process.execPath), "/tools/node",
44:     "--symlink", "usr/bin", "/bin", "--symlink", "usr/sbin", "/sbin",
45:     "--symlink", "usr/lib", "/lib", "--symlink", "usr/lib64", "/lib64",
46:     "--proc", "/proc", "--dev", "/dev", "--tmpfs", "/tmp", "--dir", "/tmp/home",
47:     "--bind", cwd, "/workspace", "--chdir", "/workspace", "--clearenv",
48:     "--setenv", "PATH", "/tools:/usr/bin:/bin", "--setenv", "HOME", "/tmp/home",
49:     "--setenv", "TMPDIR", "/tmp", "--setenv", "LANG", "C.UTF-8",
