1: #!/usr/bin/env node
2: // THE FRESH-PROCESS VERIFIER of a live run (live-run.mjs). The launcher spawns this file with `node`, in a new
3: // process that shares no memory, no open ledger handle and no cached head with the process that ran the ticks, and
4: // records ITS verdict in run.json (independent review, assignment 3, question 10: a fresh reader in the same process
5: // is not a fresh process).
6: //
7: //   node ophanim/operate/verify-run.mjs '<json: {workRoot, item, statusRoot, statusBefore: {head, files: {digest}}, verdictFile?}>'
8: //
9: // It re-opens the work ledger read-only (create: false), verifies it, takes the item's stage records FROM THE LEDGER
10: // (not from the caller), verifies every run ledger they cite and the status ledger (read-only, compared with the
11: // state before the run), and prints one JSON object (freshVerification's shape plus {pid}). With `verdictFile`, the
12: // same object is FIRST written to that file and fsync'd, so the verdict does not depend on a stdout pipe reaching the
13: // parent (independent review, assignment 3 (OpenAI gpt-6-astra extra review, 09d490f), question 10: a child exited 0
14: // with no captured verdict). Exit 0 when it verified, 1 when it did not, 2 on a usage error.
15: // Must never: write to any ledger, or take a stage list from its caller.
16: import fs from 'node:fs';
17: import {openWorkLedger} from './work-ledger.mjs';
18: import {freshVerification} from './live-run.mjs';
19: 
20: let args;
21: try { args = JSON.parse(process.argv[2] ?? ''); } catch { process.stderr.write('usage: verify-run.mjs <json {workRoot, item, statusRoot, statusBefore}>\n'); process.exit(2); }
22: let stages = [];
23: try { stages = openWorkLedger({root: args.workRoot, create: false}).stages(args.item); } catch { /* freshVerification records the work ledger's failure */ }
24: const out = {...freshVerification({workRoot: args.workRoot, stages, statusRoot: args.statusRoot, statusBefore: args.statusBefore}), pid: process.pid, stages: stages.length};
25: const line = JSON.stringify(out) + '\n';
26: if (typeof args.verdictFile === 'string' && args.verdictFile) {
27:   const fd = fs.openSync(args.verdictFile, 'wx', 0o600);
28:   try { fs.writeSync(fd, line); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
29: }
30: process.stdout.write(line);
31: process.exitCode = out.ok ? 0 : 1;

